// The Windows counterpart of the String Catalog runtime: the keys are the ones in
// LearnLayer/Resources/Localizable.xcstrings, the tables are generated by scripts/convert-xcstrings.mjs.

export type PluralForms = Record<string, string>;
export type PluralValue = { plural: PluralForms };
export type SubstitutionValue = {
  value: string;
  substitutions: Record<string, { argNum: number; plural: PluralForms }>;
};
export type LocaleValue = string | PluralValue | SubstitutionValue;
export type LocaleTable = Record<string, LocaleValue>;
export type FormatArg = string | number;

export const baseLanguage = "en";
export const supportedLanguages = ["en", "pt-PT"] as const;
export type Language = (typeof supportedLanguages)[number];

/** Portuguese is always European Portuguese here (CLAUDE.md, rule 11); anything else is English. */
export function resolveLanguage(preferred: readonly string[], stored?: string | null): Language {
  const candidates = stored ? [stored, ...preferred] : [...preferred];
  for (const candidate of candidates) {
    const tag = candidate.trim().toLowerCase();
    if (tag === "pt" || tag.startsWith("pt-") || tag.startsWith("pt_")) return "pt-PT";
    if (tag === "en" || tag.startsWith("en-") || tag.startsWith("en_")) return "en";
  }
  return baseLanguage;
}

function formatInteger(value: number, language: string): string {
  return new Intl.NumberFormat(language, { maximumFractionDigits: 0 }).format(value);
}

function formatArgument(arg: FormatArg | undefined, specifier: string, language: string): string {
  if (arg === undefined) return "";
  if (specifier === "@") return String(arg);
  const number = typeof arg === "number" ? arg : Number(arg);
  if (!Number.isFinite(number)) return String(arg);
  return formatInteger(Math.trunc(number), language);
}

/** `%@`, `%lld`, `%d`, `%ld`, their positional forms (`%1$@`, `%2$lld`) and `%%`. */
export function formatPattern(pattern: string, args: readonly FormatArg[], language: string): string {
  let next = 0;
  return pattern.replace(/%(?:(\d+)\$)?(lld|ld|d|@|%)/g, (_match, position: string | undefined, specifier: string) => {
    if (specifier === "%") return "%";
    const index = position ? Number(position) - 1 : next++;
    return formatArgument(args[index], specifier, language);
  });
}

function pluralForm(forms: PluralForms, count: FormatArg | undefined, language: string): string {
  const number = typeof count === "number" ? count : Number(count);
  const category = Number.isFinite(number) ? new Intl.PluralRules(language).select(number) : "other";
  return forms[category] ?? forms.other ?? "";
}

function firstNumber(args: readonly FormatArg[]): FormatArg | undefined {
  return args.find((arg) => typeof arg === "number") ?? args[0];
}

export function formatValue(value: LocaleValue, args: readonly FormatArg[], language: string): string {
  if (typeof value === "string") return formatPattern(value, args, language);
  if ("plural" in value) return formatPattern(pluralForm(value.plural, firstNumber(args), language), args, language);
  const filled = value.value.replace(/%#@([A-Za-z0-9_]+)@/g, (match, name: string) => {
    const substitution = value.substitutions[name];
    if (!substitution) return match;
    const arg = args[substitution.argNum - 1];
    const form = pluralForm(substitution.plural, arg, language);
    return form.replaceAll("%arg", formatArgument(arg, "lld", language)).replaceAll("%", "%%");
  });
  return formatPattern(filled, args, language);
}

export type Translator = (key: string, ...args: FormatArg[]) => string;

/**
 * `tables` are tried in order, so a platform override table can sit in front of the generated one.
 * A key that no table has is shown as written, which is what the Mac does.
 */
export function makeTranslator(language: string, ...tables: readonly (LocaleTable | undefined)[]): Translator {
  return (key, ...args) => {
    for (const table of tables) {
      const value = table?.[key];
      if (value !== undefined) return formatValue(value, args, language);
    }
    return formatPattern(key, args, language);
  };
}
